// Extrae IDs de adjuntos desde payload.parts del mensaje Gmail completo
const payload = $json.payload || {};
const messageId = $json.id;

// Cabeceras del mensaje
const headers = payload.headers || [];
const getHeader = (name) => (headers.find(h => h.name.toLowerCase() === name.toLowerCase()) || {}).value || '';

const emailFrom    = $json.From || $json.from || getHeader('From') || '';
const emailSubject = $json.Subject || $json.subject || getHeader('Subject') || '(sin asunto)'; const decodeB64Url = (d) => d ? Buffer.from(String(d).replace(/-/g,'+').replace(/_/g,'/'),'base64').toString('utf8') : ''; function extraerBody(node){ let text='',html=''; (function walk(part){ if(!part) return; const mt=(part.mimeType||'').toLowerCase(); if(mt==='text/plain'&&part.body&&part.body.data&&!text) text=decodeB64Url(part.body.data); else if(mt==='text/html'&&part.body&&part.body.data&&!html) html=decodeB64Url(part.body.data); if(part.parts) part.parts.forEach(walk); })(node); if(!text&&!html&&node&&node.body&&node.body.data) text=decodeB64Url(node.body.data); return {text,html}; } const _body = extraerBody(payload); const emailBody = _body.text || ''; const emailBodyHtml = _body.html || ''; const emailSnippet = $json.snippet || '';

// Recorre partes recursivamente para encontrar adjuntos reales
function extractAttachments(parts, depth) {
  if (!parts || depth > 6) return [];
  const result = [];
  for (const part of parts) {
    if (part.filename && part.filename.length > 0 && part.body && part.body.attachmentId) {
      result.push({
        attachmentId: part.body.attachmentId,
        fileName:     part.filename,
        mimeType:     part.mimeType || 'application/octet-stream'
      });
    }
    if (part.parts) result.push(...extractAttachments(part.parts, depth + 1));
  }
  return result;
}

const allAttachments = extractAttachments(payload.parts || [], 0);

let excelAtt = null;
let zipAtt   = null;

for (const att of allAttachments) {
  const fn = att.fileName.toLowerCase();
  const mt = att.mimeType.toLowerCase();
  if (!excelAtt && (fn.endsWith('.xlsx') || fn.endsWith('.xls') || mt.includes('spreadsheet') || mt.includes('excel') || mt.includes('openxmlformats'))) {
    excelAtt = att;
  } else if (!zipAtt && (fn.endsWith('.zip') || mt.includes('zip') || mt.includes('x-zip') || mt.includes('compressed'))) {
    zipAtt = att;
  }
}

return [{ json: {
  messageId,
  emailFrom,
  emailSubject,
  emailBody,
  emailBodyHtml,
  emailSnippet,
  hasExcel:          !!excelAtt,
  hasZip:            !!zipAtt,
  excelAttachmentId: excelAtt ? excelAtt.attachmentId : '',
  excelFileName:     excelAtt ? excelAtt.fileName     : '',
  excelMimeType:     excelAtt ? excelAtt.mimeType     : '',
  zipAttachmentId:   zipAtt   ? zipAtt.attachmentId   : '',
  zipFileName:       zipAtt   ? zipAtt.fileName       : '',
  zipMimeType:       zipAtt   ? zipAtt.mimeType       : ''
}}];
